import csv
import json
import math
import re
from collections import defaultdict
from datetime import datetime, timezone
from statistics import median


DATA_PATH = "/app/dataset/data.csv"
OUTPUT_PATH = "/app/answer.json"

START = datetime(2025, 10, 1, 0, 0, 0, tzinfo=timezone.utc)
END = datetime(2025, 12, 31, 23, 59, 59, tzinfo=timezone.utc)

ITEMS_RE = re.compile(r"items=([+-]?\d+)")
ADJ_RE = re.compile(r"adj=([+-]?\d+(?:\.\d+)?)%")
FEE_RE = re.compile(r"fee=([+-]?\d+(?:\.\d+)?)")
WAIVE_RE = re.compile(r"waive=true", re.IGNORECASE)


def parse_amount(value: str) -> float:
    if value is None:
        return math.nan

    value = value.strip()
    if not value:
        return math.nan

    is_negative = "CR" in value or (value.startswith("(") and value.endswith(")")) or ("-" in value)

    value = value.replace("C1", "").replace("C2", "")
    cleaned = "".join(ch for ch in value if ch.isdigit() or ch in ",.")
    if not cleaned:
        return math.nan

    comma_count = cleaned.count(",")
    dot_count = cleaned.count(".")

    if comma_count and dot_count:
        last_comma = cleaned.rfind(",")
        last_dot = cleaned.rfind(".")
        if last_comma > last_dot:
            decimal_sep = ","
            thousands_sep = "."
        else:
            decimal_sep = "."
            thousands_sep = ","
        normalized = cleaned.replace(thousands_sep, "").replace(decimal_sep, ".")
    elif comma_count or dot_count:
        sep = "," if comma_count else "."
        last_sep = cleaned.rfind(sep)
        digits_after = len(cleaned) - last_sep - 1
        if digits_after == 2:
            whole, frac = cleaned.rsplit(sep, 1)
            normalized = whole.replace(sep, "") + "." + frac
        else:
            normalized = cleaned.replace(sep, "")
    else:
        normalized = cleaned

    if normalized in {"", "."}:
        return math.nan

    amount = float(normalized)
    return -amount if is_negative else amount


def parse_notes(notes: str) -> tuple[int | None, float, float, bool]:
    notes = notes or ""

    items_match = ITEMS_RE.search(notes)
    adj_match = ADJ_RE.search(notes)
    fee_match = FEE_RE.search(notes)

    items = int(items_match.group(1)) if items_match else None
    adj_pct = float(adj_match.group(1)) / 100.0 if adj_match else 0.0
    fee = float(fee_match.group(1)) if fee_match else 0.0
    waive = bool(WAIVE_RE.search(notes))

    return items, adj_pct, fee, waive


def parse_event_time(value: str) -> datetime | None:
    if not value:
        return None
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def compute_net(base_amount: float, adj_pct: float, fee: float, waive: bool) -> float:
    if math.isnan(base_amount):
        return math.nan

    net = base_amount * (1.0 + adj_pct) + fee
    if waive:
        net = 0.0
    return net


def is_real_number(value: float) -> bool:
    return math.isfinite(value)


def answer() -> list[str]:
    rows = []
    with open(DATA_PATH, newline="") as f:
        reader = csv.DictReader(f)
        for file_order, row in enumerate(reader):
            base_amount = parse_amount(row["amount_str"])
            items, adj_pct, fee, waive = parse_notes(row["notes"])
            net = compute_net(base_amount, adj_pct, fee, waive)
            event_time = parse_event_time(row["event_time"])
            rows.append(
                {
                    "record_id": row["record_id"],
                    "event_time": event_time,
                    "region": row["region"],
                    "channel": row["channel"],
                    "items": items,
                    "net": net,
                    "file_order": file_order,
                }
            )

    best_by_record_id = {}
    min_dt = datetime.min.replace(tzinfo=timezone.utc)

    def dedupe_key(row: dict) -> tuple:
        return (
            row["event_time"] is not None,
            row["event_time"] or min_dt,
            1 if is_real_number(row["net"]) else 0,
            -row["file_order"],
        )

    for row in rows:
        record_id = row["record_id"]
        current = best_by_record_id.get(record_id)
        if current is None or dedupe_key(row) > dedupe_key(current):
            best_by_record_id[record_id] = row

    filtered_rows = []
    for row in best_by_record_id.values():
        event_time = row["event_time"]
        if event_time is None:
            continue
        if not (START <= event_time <= END):
            continue
        if row["channel"].strip().lower() == "phone":
            continue
        if not is_real_number(row["net"]):
            continue

        row["month"] = event_time.strftime("%Y-%m")
        filtered_rows.append(row)

    grouped_nets = defaultdict(list)
    for row in filtered_rows:
        grouped_nets[(row["region"], row["month"])].append(row["net"])

    group_stats = {}
    for key, values in grouped_nets.items():
        group_median = median(values)
        group_mad = median(abs(value - group_median) for value in values)
        group_stats[key] = (group_median, group_mad)

    for row in filtered_rows:
        group_median, group_mad = group_stats[(row["region"], row["month"])]
        if group_mad == 0:
            robust_z = 0.0
        else:
            robust_z = 0.6745 * (row["net"] - group_median) / group_mad

        items_eff = row["items"] if row["items"] is not None else 1
        items_eff = max(items_eff, 1)

        row["robust_z"] = robust_z
        row["anomaly_score"] = abs(robust_z) * math.log1p(items_eff)

    filtered_rows.sort(
        key=lambda row: (
            -row["anomaly_score"],
            -abs(row["robust_z"]),
            -row["event_time"].timestamp(),
            row["record_id"],
        )
    )

    return [row["record_id"] for row in filtered_rows[:10]]


if __name__ == "__main__":
    with open(OUTPUT_PATH, "w") as f:
        json.dump(answer(), f, default=list)
